INSERT INTO public.interactive_stories(slug,revision,title,subtitle,description,level,minutes,free_preview,published,document) VALUES('first-school-day',1,'Первый день в школе','A Place at the Table','Новая школа, потерянная карточка и свободное место за столом. Познакомься с одноклассниками, попроси помощь и выбери, как закончится твой первый день.','A1',10,true,true,'{"start":"n1","nodes":{"n1":{"speaker":"Narrator","text":"It is your first day at a new school. Your bag is blue. Your classroom is Room 12. At the door, a boy has a big box. A girl has a school map. The bell rings. You have two minutes.","choices":[{"id":"a","text":"Hello! Can I help with the box?","next":"n2"},{"id":"b","text":"Excuse me. Where is Room 12?","next":"n3"}],"vocabulary":[{"word":"bell","translation":"школьный звонок"}],"grammar":"Can I help? — вежливое предложение помощи. Excuse me — способ привлечь внимание незнакомого человека."},"n2":{"speaker":"Ben","text":"Thank you! My name is Ben. These are our class books. The box is heavy. We take it to Room 12 together. A small yellow card falls from a book. There is no name on it.","choices":[{"id":"a","text":"Let us take the card to class.","next":"n4"}],"vocabulary":[{"word":"heavy","translation":"тяжёлый"}]},"n3":{"speaker":"Mia","text":"I am Mia. Room 12 is next to the library. Come with me. There is a yellow card on the floor near the library door. It has a picture of a tree. Is it a library card?","choices":[{"id":"a","text":"Let us ask our teacher.","next":"n4"}],"vocabulary":[{"word":"next to","translation":"рядом с"}]},"n4":{"speaker":"Ms Green","text":"Welcome! I am Ms Green. This is our class. The yellow card is for our lunch game. One student needs it. Please sit down first. There is a chair by the window and a chair near the door.","choices":[{"id":"a","text":"Introduce yourself to the class.","next":"n5"}],"vocabulary":[{"word":"chair","translation":"стул"}],"grammar":"I am / You are / This is — формы глагола be в настоящем времени. I am new здесь значит «Я новенький / новенькая»."},"n5":{"speaker":"Ms Green","text":"Please tell us your name. Then say that this is your first day. Ben smiles. Mia gives you a pencil. You want to speak to the whole class. Choose the sentence for your introduction.","choices":[{"id":"a","text":"Hello! I am new here.","next":"n6","correct":true},{"id":"b","text":"Hello! I is new here.","next":"n7","correct":false}],"vocabulary":[{"word":"new","translation":"новый; новенький"}],"grammar":"Глагол be: I am, he/she/it is, you/we/they are.","question":"Как правильно представиться?","explanation":"Правильно: I am new here. С I используется am. Is относится к he, she, it."},"n6":{"speaker":"Ben","text":"Welcome! Your English is clear. You sit by the window. Ben shows you the class timetable. Lunch is at twelve. There is a small tree in the picture on the lunch menu. It is the same tree as on your card.","choices":[{"id":"a","text":"Ask about the yellow card.","next":"n8"}],"vocabulary":[{"word":"timetable","translation":"расписание"}]},"n7":{"speaker":"Mia","text":"You say, \"I is new here.\" Mia speaks quietly: \"I am new here.\" You try again. Ms Green smiles. A mistake is OK. Mia shows you the lunch menu. There is a small tree on it, like the tree on your card.","choices":[{"id":"a","text":"Try again, then ask about the card.","next":"n8"}],"vocabulary":[{"word":"quietly","translation":"тихо"}]},"n8":{"speaker":"Narrator","text":"At break, Ben and Mia look at the card. Ben wants to ask the lunch cook. Mia wants to look at the school garden. The card has a tree, but it also has a small cup. Where do you go?","choices":[{"id":"a","text":"Let us ask the cook.","next":"n9"},{"id":"b","text":"Let us look in the garden.","next":"n10"}],"vocabulary":[{"word":"break","translation":"перемена"}]},"n9":{"speaker":"Cook","text":"The cook is busy, but she looks at the card. \"This is a table card,\" she says. \"The tree table is for new students and their friends. But the card needs one more thing. Ask your teacher about the cup.\"","choices":[{"id":"a","text":"Thank the cook and go back.","next":"n11"}],"vocabulary":[{"word":"cook","translation":"повар"}]},"n10":{"speaker":"Mia","text":"The garden is small and green. There is a tree, a bench and a red cup. A sign says: \"Please bring your own cup to lunch.\" Mia laughs. \"Our tree is outside, but the card is for a table inside!\"","choices":[{"id":"a","text":"Take your own cup from your bag.","next":"n11"}],"vocabulary":[{"word":"bring","translation":"приносить"}]},"n11":{"speaker":"Ms Green","text":"Yes, the tree table is for new students. Please bring your own cup. There are three places at the table. You have the card. Ben and Mia are waiting near the lunch room. You want them to sit with you.","choices":[{"id":"a","text":"Invite your new friends.","next":"n12"}],"vocabulary":[{"word":"place","translation":"место"}]},"n12":{"speaker":"Narrator","text":"You see Ben and Mia at the door. You want to sit together at the tree table. You have three places, so both friends can come. Choose a question to invite them.","choices":[{"id":"a","text":"Can you sit with me?","next":"n13","correct":true},{"id":"b","text":"Can you to sit with me?","next":"n14","correct":false}],"vocabulary":[{"word":"together","translation":"вместе"}],"grammar":"Can + подлежащее + глагол: Can you sit? Не добавляем to после can.","question":"Как пригласить друзей сесть вместе?","explanation":"Can you sit with me? — вопрос-приглашение. После can идёт начальная форма sit, без to."},"n13":{"speaker":"Ben","text":"Yes, thank you! We can sit with you. Ben carries the water. Mia carries three plates. You put the yellow card on the table. Now another new student is standing at the door with a lunch bag.","choices":[{"id":"a","text":"Look at the new student.","next":"n15"}],"vocabulary":[{"word":"plate","translation":"тарелка"}]},"n14":{"speaker":"Mia","text":"Mia understands you, but she helps: \"Can you sit with me? No to.\" You say it again. Ben and Mia sit down. You see another new student at the door. The tree table has three places, and all three are full.","choices":[{"id":"a","text":"Think about another place.","next":"n16"}],"vocabulary":[{"word":"full","translation":"полный; занятый"}]},"n15":{"speaker":"Narrator","text":"The new student looks at your yellow card. \"I am new, too,\" he says. His name is Leo. Your table is full, but the next table has a free chair. Ms Green is near the door. You can ask for help.","choices":[{"id":"a","text":"Ms Green, can we have one more chair?","next":"n17"},{"id":"b","text":"Let us take our lunch to the next table.","next":"n18"}],"vocabulary":[{"word":"one more","translation":"ещё один"}]},"n16":{"speaker":"Leo","text":"I am Leo. Is this the new students table? You show him the yellow card. You can ask Ms Green to move a chair. Or you can show Leo the next table and meet him after lunch.","choices":[{"id":"a","text":"Let us ask the teacher for a chair.","next":"n18"},{"id":"b","text":"You can sit there. See you after lunch!","next":"n19"}],"vocabulary":[{"word":"after","translation":"после"}]},"n17":{"speaker":"Narrator","text":"Ms Green brings a chair. Now four friends sit at the tree table. You give Leo a cup. He smiles. The card is small, but your table is big enough. At home, you say, \"My new school is a good place.\"","choices":[],"vocabulary":[{"word":"enough","translation":"достаточно"}],"ending":{"title":"Стол для всех","reward":"Значок «Первое приглашение»"}},"n18":{"speaker":"Narrator","text":"You and your friends make a new place for Leo. Lunch is a little late, but nobody eats alone. Ben writes four names on the back of the card. Tomorrow you can meet at the same door and go to class together.","choices":[],"vocabulary":[{"word":"alone","translation":"в одиночестве"}],"ending":{"title":"Четыре новых имени","reward":"Значок «Новая компания»"}},"n19":{"speaker":"Narrator","text":"Leo sits at the next table. After lunch, you meet him at the door. \"Hello, I am new here, too,\" you say. He has a red bag. You walk to Room 12 together. There is time for a new friend after lunch.","choices":[],"vocabulary":[{"word":"walk","translation":"идти пешком"}],"ending":{"title":"Дружба после обеда","reward":"Значок «Второй шанс»"}}}}'::jsonb) ON CONFLICT(slug,revision) DO NOTHING;
INSERT INTO public.interactive_stories(slug,revision,title,subtitle,description,level,minutes,free_preview,published,document) VALUES('online-friend',1,'Новый друг в интернете','The Pixel Garden','Совместный пиксельный сад почти готов, но незнакомый участник просит личный контакт. Реши, кому доверять, как проверить участника и кому достанется авторство.','A2',12,false,true,'{"start":"n1","nodes":{"n1":{"speaker":"Narrator","text":"You are building a pixel garden in an online art club. Everyone uses a nickname. A new member, CloudFox, sends a picture of a blue flower. \"Can I help with your garden?\" they ask. The club exhibition opens tomorrow.","choices":[{"id":"a","text":"Ask CloudFox about the flower.","next":"n2"},{"id":"b","text":"Read CloudFox’s public club profile.","next":"n3"}],"vocabulary":[{"word":"nickname","translation":"псевдоним"}]},"n2":{"speaker":"CloudFox","text":"I drew this flower yesterday. It looks like a little umbrella. I can make more colours if you like. You ask where it should go. CloudFox suggests the empty corner near your pond. They do not ask to change the whole garden.","choices":[{"id":"a","text":"Suggest working in the club room.","next":"n4"}],"vocabulary":[{"word":"pond","translation":"пруд"}]},"n3":{"speaker":"Narrator","text":"The profile is new, but it includes two public drawings. One is a blue flower. There is no real name or address. The club rules say new artists can join shared projects in the public work room. A new profile is not proof of a bad person.","choices":[{"id":"a","text":"Invite CloudFox to the public work room.","next":"n4"}],"vocabulary":[{"word":"shared","translation":"совместный"}]},"n4":{"speaker":"CloudFox","text":"Let us add the flowers tonight. Can you give me your phone number? It is easier to send files that way. You like the drawing, but the club already has a safe file area. You can be friendly and keep personal information private.","choices":[{"id":"a","text":"Choose your reply.","next":"n5"}],"vocabulary":[{"word":"private","translation":"личный; закрытый"}],"grammar":"Can we…? — мягкое предложение совместного действия: Can we use the club room?"},"n5":{"speaker":"Narrator","text":"You want to continue the project without giving your phone number. The club room lets members send drawings. Choose the reply that keeps a clear boundary and offers another way to work together.","choices":[{"id":"a","text":"Can we use the club file area instead?","next":"n6","correct":true},{"id":"b","text":"Here is my number. Please keep it secret.","next":"n7","correct":false}],"vocabulary":[{"word":"instead","translation":"вместо этого"}],"grammar":"Can we use… instead? — вежливое предложение альтернативы, без передачи личных данных.","question":"Which reply keeps your information private?","explanation":"Можно отказаться от личного контакта и предложить площадку клуба. Вежливость не обязывает делиться номером."},"n6":{"speaker":"CloudFox","text":"Of course. I did not know about that area. Thanks for showing me. CloudFox uploads the flower picture there. You download the image through the club tools. It is only a picture, and you can see it before adding it to the project.","choices":[{"id":"a","text":"Plan the garden together.","next":"n8"}],"vocabulary":[{"word":"upload","translation":"загрузить на сервер"}]},"n7":{"speaker":"Narrator","text":"Before you send anything, the club reminds you not to post phone numbers. You remove the unsent message. \"Let us use the file area,\" you write instead. CloudFox agrees. You can change your mind about sharing personal information.","choices":[{"id":"a","text":"Continue in the club room.","next":"n8"}],"vocabulary":[{"word":"unsent","translation":"неотправленный"}]},"n8":{"speaker":"CloudFox","text":"The garden needs a path and a sign. CloudFox can draw one of them. You have time to make the other. A member called Reed leaves a comment: \"That flower looks familiar.\" There is no explanation yet.","choices":[{"id":"a","text":"Ask Reed for the public source.","next":"n9"},{"id":"b","text":"Ask CloudFox how they made the flower.","next":"n10"}],"vocabulary":[{"word":"source","translation":"источник"}]},"n9":{"speaker":"Reed","text":"I saw a similar flower in last month’s public challenge. Here is its title in the club archive. You find a red flower by an artist called Kite. The shape is similar, but the colours and leaves are different. It is worth asking before making an accusation.","choices":[{"id":"a","text":"Compare the two public drawings.","next":"n11"}],"vocabulary":[{"word":"similar","translation":"похожий"}]},"n10":{"speaker":"CloudFox","text":"I used the club’s umbrella-flower challenge sheet. It says everyone can draw the same basic shape. I changed the leaves. CloudFox shows you the challenge title in the public archive. You can check the instructions yourself rather than just accept the claim.","choices":[{"id":"a","text":"Read the challenge instructions.","next":"n11"}],"vocabulary":[{"word":"instructions","translation":"инструкции"}]},"n11":{"speaker":"Narrator","text":"The challenge allows artists to use the basic shape if they credit the club template. CloudFox forgot the credit line. The garden can still enter the exhibition if you add it before midnight. You need to tell the moderator what you have checked.","choices":[{"id":"a","text":"Write a short update.","next":"n12"}],"vocabulary":[{"word":"credit","translation":"указание авторства или источника"}],"grammar":"Present perfect связывает сделанное с результатом сейчас: We have checked the instructions — проверили, и теперь знаем условия."},"n12":{"speaker":"Moderator","text":"Have you checked the template instructions? You checked them together a moment ago. The result matters now: you can add the correct credit line. Choose the sentence that fits the moderator’s question.","choices":[{"id":"a","text":"We have checked the instructions.","next":"n13","correct":true},{"id":"b","text":"We have check the instructions.","next":"n14","correct":false}],"vocabulary":[{"word":"checked","translation":"проверили"}],"grammar":"Present perfect: have/has + past participle. Для правильного check третья форма — checked.","question":"Choose the correct update.","explanation":"We have checked the instructions. После have нужна третья форма: checked. Check без окончания здесь не подходит."},"n13":{"speaker":"Moderator","text":"Thanks for the clear update. The template can be used with a credit line. Please add the line and list both artists. CloudFox writes: \"I was worried you would stop talking to me.\" You reply that checking a source helps everyone.","choices":[{"id":"a","text":"Choose how to finish the project.","next":"n15"}],"vocabulary":[{"word":"both","translation":"оба"}]},"n14":{"speaker":"Moderator","text":"I understand. Write \"We have checked\" when the check is complete. The credit information is useful, but I still need your corrected project note. You have time to fix the English and add the source before midnight.","choices":[{"id":"a","text":"Decide what to submit.","next":"n16"}],"vocabulary":[{"word":"complete","translation":"завершённый"}]},"n15":{"speaker":"CloudFox","text":"The sign is ready: \"A small garden by two artists, using the club flower template.\" There is space for a short note. You can submit together now or ask to present the work in tomorrow’s public club session.","choices":[{"id":"a","text":"Submit the garden with shared credit.","next":"n17"},{"id":"b","text":"Ask for a public presentation together.","next":"n18"}],"vocabulary":[{"word":"submit","translation":"отправить на рассмотрение"}]},"n16":{"speaker":"Narrator","text":"You correct the note and add the template credit. There are only ten minutes left. CloudFox asks if you can still finish together. You can ask the moderator to check the note now or save the garden for the next exhibition.","choices":[{"id":"a","text":"Ask the moderator to check the final note.","next":"n18"},{"id":"b","text":"Save it for the next exhibition.","next":"n19"}],"vocabulary":[{"word":"final","translation":"окончательный"}]},"n17":{"speaker":"Narrator","text":"The garden appears in the exhibition with both nicknames and the template credit. CloudFox adds a tiny umbrella beside the pond. You have a new art partner, not a stranger with your personal details. Tomorrow’s plan is already in the public club room.","choices":[],"vocabulary":[{"word":"details","translation":"сведения"}],"ending":{"title":"Сад с двумя подписями","reward":"Значок «Надёжный соавтор»"}},"n18":{"speaker":"Narrator","text":"In the public session, you explain how the garden was made. The moderator checks the note before showing it. CloudFox describes the blue flower. Reed thanks you for checking the source calmly. Your first shared project becomes a useful example for the whole club.","choices":[],"vocabulary":[{"word":"calmly","translation":"спокойно"}],"ending":{"title":"Открытая мастерская","reward":"Значок «Спокойный диалог»"}},"n19":{"speaker":"Narrator","text":"You save a draft with the correct source and both nicknames. There is no exhibition badge today, but you have not lost the garden. CloudFox agrees to add a night sky next week. A good online friendship can grow slowly, in a shared space with clear rules.","choices":[],"vocabulary":[{"word":"draft","translation":"черновик"}],"ending":{"title":"Сад на следующую неделю","reward":"Значок «Свои границы»"}}}}'::jsonb) ON CONFLICT(slug,revision) DO NOTHING;
INSERT INTO public.interactive_stories(slug,revision,title,subtitle,description,level,minutes,free_preview,published,document) VALUES('server-mystery',1,'Тайна игрового сервера','The Clock Beneath Spawn','На игровом сервере каждую ночь исчезает мост. Изучи журнал событий, поговори с командой и найди объяснение, прежде чем город лишится главной переправы.','B1',15,false,true,'{"start":"n1","nodes":{"n1":{"speaker":"Narrator","text":"Every morning, the bridge beside the spawn point is missing. By lunchtime it returns. Nobody has lost an item, but players are blaming each other. You help run the community noticeboard. Tonight you receive a message: \"Watch the clock beneath spawn.\"","choices":[{"id":"a","text":"Inspect the public event log.","next":"n2"},{"id":"b","text":"Ask the night-shift builder what happened.","next":"n3"}],"vocabulary":[{"word":"spawn point","translation":"точка появления игрока"}]},"n2":{"speaker":"Narrator","text":"The event log shows a scheduled world-copy job at 02:00. A bridge update appears at 02:01, but its author is a maintenance account. The same sequence happened three nights in a row. The clock message may refer to a schedule rather than a hidden object.","choices":[{"id":"a","text":"Share the timestamps with the team.","next":"n4"}],"vocabulary":[{"word":"scheduled","translation":"запланированный"}]},"n3":{"speaker":"Nora","text":"I finished the bridge at one in the morning. When I returned after two, it had gone. I took a screenshot because I thought I had saved it incorrectly. Nora’s screenshot shows the old wooden bridge, not the new stone one described on the noticeboard.","choices":[{"id":"a","text":"Compare her screenshot with the log.","next":"n4"}],"vocabulary":[{"word":"screenshot","translation":"снимок экрана"}]},"n4":{"speaker":"Narrator","text":"You now have a log and a screenshot. A public sign names the stone bridge as the latest version. The log says the night copy loads a map made before that version existed. You need to describe the order of events without accusing a player.","choices":[{"id":"a","text":"Explain the timeline to Nora.","next":"n5"}],"vocabulary":[{"word":"timeline","translation":"последовательность событий"}],"grammar":"Past perfect обозначает действие раньше другого момента в прошлом: The copy had started before the bridge disappeared."},"n5":{"speaker":"Nora","text":"Did the map copy start before the bridge disappeared? The copy started at 02:00; the bridge disappeared at 02:01. Choose the sentence that makes this order clear.","choices":[{"id":"a","text":"The copy had started before the bridge disappeared.","next":"n6","correct":true},{"id":"b","text":"The copy starts tomorrow, so it caused yesterday’s loss.","next":"n7","correct":false}],"vocabulary":[{"word":"before","translation":"до того как"}],"grammar":"The copy had started before the bridge disappeared. Had started показывает действие, которое произошло раньше другого прошедшего события.","question":"Which sentence describes the earlier action?","explanation":"The copy had started before the bridge disappeared. Had started показывает действие, которое произошло раньше другого прошедшего события."},"n6":{"speaker":"Nora","text":"That makes sense. The missing bridge may be an old map returning, not someone removing blocks. Nora gives you access to a read-only test world. Its clock is set to two in the morning, so you can observe the copy without touching the main server.","choices":[{"id":"a","text":"Choose a safe investigation.","next":"n8"}],"vocabulary":[{"word":"read-only","translation":"только для чтения"}]},"n7":{"speaker":"Narrator","text":"Nora points to the times again. Tomorrow cannot explain yesterday’s event. You rewrite the note with \"had started\" and keep both pieces of evidence. The error in your explanation has not changed the server. You can still investigate in a read-only test world.","choices":[{"id":"a","text":"Check the evidence safely.","next":"n8"}],"vocabulary":[{"word":"evidence","translation":"доказательства; фактические данные"}]},"n8":{"speaker":"Narrator","text":"The test world has a small clock under the spawn platform. It displays the backup version, not the time. You can compare its number with the public map archive or ask the maintenance volunteer to explain the label.","choices":[{"id":"a","text":"Compare the archive version numbers.","next":"n9"},{"id":"b","text":"Ask the maintenance volunteer.","next":"n10"}],"vocabulary":[{"word":"backup","translation":"резервная копия"}]},"n9":{"speaker":"Narrator","text":"The clock reads 14, while the current map is version 16. Version 14 has the wooden bridge in Nora’s screenshot. A note beside version 16 says \"restore after market cleanup\". Something still treats the old cleanup map as the normal night map.","choices":[{"id":"a","text":"Find the cleanup schedule.","next":"n11"}],"vocabulary":[{"word":"restore","translation":"восстановить"}]},"n10":{"speaker":"Ivo","text":"The clock marks our recovery map. We used version 14 during the market event. I thought I had removed its schedule. Ivo does not have permission to change the main schedule alone. He asks you to find the cleanup entry so an administrator can review it.","choices":[{"id":"a","text":"Look for the remaining cleanup entry.","next":"n11"}],"vocabulary":[{"word":"recovery","translation":"восстановление"}]},"n11":{"speaker":"Narrator","text":"The cleanup entry is still active. It loads version 14 at night, then version 16 at noon. A comment says \"temporary\". You have found a likely explanation, but changing the main schedule is an administrator’s job. Your report needs a safe recommendation.","choices":[{"id":"a","text":"Write a conditional recommendation.","next":"n12"}],"vocabulary":[{"word":"temporary","translation":"временный"}],"grammar":"First conditional: If + present simple, will + начальная форма. Это вероятное последствие будущего условия."},"n12":{"speaker":"Administrator","text":"What will happen if we disable the old cleanup job? The test shows version 16 stays loaded without it. Choose a clear prediction based on that result.","choices":[{"id":"a","text":"If we disable the old job, the new bridge will stay.","next":"n13","correct":true},{"id":"b","text":"If we will disable the old job, the new bridge stay.","next":"n14","correct":false}],"vocabulary":[{"word":"disable","translation":"отключить"}],"grammar":"В обычном first conditional не ставим will в if-части: If we disable…, … will stay.","question":"Choose the correct conditional sentence.","explanation":"If we disable the old job, the new bridge will stay. После if — present simple, в результате — will + stay."},"n13":{"speaker":"Administrator","text":"Your recommendation is clear. I can disable the old job after a backup, or move it to the test server for one more night. Both are controlled changes. You also have enough evidence to correct the public rumour that a player destroyed the bridge.","choices":[{"id":"a","text":"Choose the next controlled step.","next":"n15"}],"vocabulary":[{"word":"rumour","translation":"слух"}]},"n14":{"speaker":"Administrator","text":"I understand the idea, but please correct the report before I approve a change. Write \"If we disable…, the bridge will stay.\" A second administrator is available tomorrow. You can request a reviewed test then, or publish what is confirmed and leave the cause provisional.","choices":[{"id":"a","text":"Decide how to report the finding.","next":"n16"}],"vocabulary":[{"word":"provisional","translation":"предварительный"}]},"n15":{"speaker":"Nora","text":"The bridge is crowded this evening. People want an answer, but you should not promise more than the test supports. The administrator is ready with a backup. Do you recommend fixing the schedule now or watching it once more in the test world?","choices":[{"id":"a","text":"Recommend the backed-up schedule fix.","next":"n17"},{"id":"b","text":"Request one more night in the test world.","next":"n18"}],"vocabulary":[{"word":"supports","translation":"подтверждает"}]},"n16":{"speaker":"Narrator","text":"You correct the English and list the timestamps. Your report separates the observed map changes from the suspected schedule problem. You can ask for a reviewed test tomorrow, or post a careful notice now without claiming that the mystery is fully solved.","choices":[{"id":"a","text":"Request tomorrow’s reviewed test.","next":"n18"},{"id":"b","text":"Publish only the confirmed findings.","next":"n19"}],"vocabulary":[{"word":"suspected","translation":"предполагаемый"}]},"n17":{"speaker":"Narrator","text":"After taking a backup, the administrator disables the obsolete job. The next morning, the stone bridge is still there. Your notice explains the schedule error and clears the accused players. Nora adds a small clock design to the bridge, this time as decoration rather than a warning.","choices":[],"vocabulary":[{"word":"obsolete","translation":"устаревший"}],"ending":{"title":"Мост остаётся","reward":"Значок «Хранитель переправы»"}},"n18":{"speaker":"Narrator","text":"The team watches another copy cycle in the test world. It reproduces the problem exactly. Two administrators then approve the schedule fix. The bridge returns permanently a day later. Players remember the extra wait, but they also see a clear record of how the team checked its answer.","choices":[],"vocabulary":[{"word":"reproduce","translation":"воспроизвести"}],"ending":{"title":"Разгадка на тестовом мире","reward":"Значок «Проверка прежде решения»"}},"n19":{"speaker":"Narrator","text":"Your notice says the bridge changes match a scheduled map copy and that nobody has evidence of deliberate damage. The main fix waits for review. The bridge may disappear once more, but the accusations stop. You leave a precise report that the next administrator can continue without guessing.","choices":[],"vocabulary":[{"word":"deliberate","translation":"намеренный"}],"ending":{"title":"Честный предварительный отчёт","reward":"Значок «Точные слова»"}}}}'::jsonb) ON CONFLICT(slug,revision) DO NOTHING;
INSERT INTO public.interactive_stories(slug,revision,title,subtitle,description,level,minutes,free_preview,published,document) VALUES('unknown-city',1,'Путешествие в неизвестный город','The City That Changed Its Signs','В незнакомом городе меняют названия улиц, а твой билет ведёт к закрытому причалу. Собери маршрут из разговоров, карт и объявлений и реши, ради чего менять планы.','B2',18,false,true,'{"start":"n1","nodes":{"n1":{"speaker":"Narrator","text":"Your train arrives in Bellwater on the morning of its annual river festival. You booked a workshop at North Quay, yet the station map calls it Foundry Steps. Your phone has little charge, and the visitor desk will not open for another hour. Two volunteers are folding paper signs nearby.","choices":[{"id":"a","text":"Ask a volunteer about the two names.","next":"n2"},{"id":"b","text":"Compare the station map with your printed ticket.","next":"n3"}],"vocabulary":[{"word":"quay","translation":"набережная; причал"}]},"n2":{"speaker":"Volunteer","text":"Foundry Steps is the old name. The festival uses it to celebrate the city’s industrial history. Unfortunately, some signs have already changed and others have not. The volunteer circles the river on your ticket and warns that the footbridge is closed for a rehearsal until eleven.","choices":[{"id":"a","text":"Ask for a route that avoids the bridge.","next":"n4"}],"vocabulary":[{"word":"rehearsal","translation":"репетиция"}]},"n3":{"speaker":"Narrator","text":"The ticket includes a small outline of three warehouses beside the river. The station map has the same outline at Foundry Steps. The names differ, but the buildings match. A notice under the map says the footbridge is closed until eleven for a festival rehearsal.","choices":[{"id":"a","text":"Look for an alternative crossing.","next":"n4"}],"vocabulary":[{"word":"outline","translation":"контур; очертание"}]},"n4":{"speaker":"Narrator","text":"A café owner offers directions while serving the morning queue. There is a tram to the south bank and a pedestrian ferry from Mill Lane. You need to confirm whether the ferry runs today, rather than assume a normal weekday timetable applies during the festival.","choices":[{"id":"a","text":"Ask an indirect question.","next":"n5"}],"vocabulary":[{"word":"pedestrian","translation":"пешеходный"}],"grammar":"В косвенном вопросе после Could you tell me порядок слов прямой: whether the ferry is running, а не whether is the ferry running."},"n5":{"speaker":"Café owner","text":"I can check the festival timetable for you. What would you like to know? You want to ask politely whether the ferry is operating today.","choices":[{"id":"a","text":"Could you tell me whether the ferry is running today?","next":"n6","correct":true},{"id":"b","text":"Could you tell me whether is the ferry running today?","next":"n7","correct":false}],"vocabulary":[{"word":"whether","translation":"ли; вводит косвенный вопрос"}],"grammar":"Could you tell me + whether + подлежащее + сказуемое. Вложенная часть не использует вопросительную инверсию.","question":"Choose the correctly ordered indirect question.","explanation":"Could you tell me whether the ferry is running today? Внутри косвенного вопроса подлежащее the ferry стоит перед is."},"n6":{"speaker":"Café owner","text":"It is running, but only from the temporary landing behind the mill. The usual stop is fenced off. She draws a square beside the word \"mill\" on your ticket. The tram is simpler, although it will take twenty minutes longer. Your workshop starts in forty minutes.","choices":[{"id":"a","text":"Choose your route.","next":"n8"}],"vocabulary":[{"word":"landing","translation":"место высадки; пристань"}]},"n7":{"speaker":"Café owner","text":"You mean whether the ferry is running? Yes, from a temporary landing behind the mill. She repeats the question with the subject before the verb, then draws the landing on your ticket. You still have time for the ferry; the tram is slower but easier to find.","choices":[{"id":"a","text":"Choose with the new information.","next":"n8"}],"vocabulary":[{"word":"fenced off","translation":"огороженный; закрытый забором"}]},"n8":{"speaker":"Narrator","text":"Outside, a musician asks whether you have seen the festival rehearsal. It is beside the closed bridge, along the way to the mill. You can go directly to the temporary landing or allow five minutes to hear the music and ask the stewards about access.","choices":[{"id":"a","text":"Head directly to the mill landing.","next":"n9"},{"id":"b","text":"Stop briefly at the rehearsal.","next":"n10"}],"vocabulary":[{"word":"steward","translation":"распорядитель; сотрудник мероприятия"}]},"n9":{"speaker":"Narrator","text":"The temporary landing is marked by a blue board, not by the yellow ferry symbol on your old map. A passenger points out a second notice: the last return boat leaves at four. You photograph the notice and keep enough battery to show it later without searching online.","choices":[{"id":"a","text":"Read the workshop organiser’s notice.","next":"n11"}],"vocabulary":[{"word":"return boat","translation":"обратный рейс лодки"}]},"n10":{"speaker":"Steward","text":"The musicians are rehearsing a piece inspired by the old foundry. A steward says the workshop organiser has moved the afternoon session to the covered market because rain is expected. She directs you to the mill landing, where the organiser has posted a written update.","choices":[{"id":"a","text":"Go to the landing and check the update.","next":"n11"}],"vocabulary":[{"word":"foundry","translation":"литейный завод"}]},"n11":{"speaker":"Narrator","text":"The organiser’s notice confirms two locations: morning at North Quay, afternoon at the covered market. Visitors may choose either session. The morning workshop will begin outdoors despite the forecast, but the afternoon one is sheltered. You consider how the bridge closure affected your plans.","choices":[{"id":"a","text":"Describe an unreal alternative.","next":"n12"}],"vocabulary":[{"word":"sheltered","translation":"защищённый от непогоды"}],"grammar":"Third conditional описывает нереальное прошлое: If + had + V3, would have + V3."},"n12":{"speaker":"Narrator","text":"The bridge was closed, so you looked for another route. Imagine the opposite situation in the past. Which sentence expresses that unreal alternative?","choices":[{"id":"a","text":"If the bridge had been open, I would have walked across it.","next":"n13","correct":true},{"id":"b","text":"If the bridge would be open yesterday, I will walk across it.","next":"n14","correct":false}],"vocabulary":[{"word":"across","translation":"через; на другую сторону"}],"grammar":"If the bridge had been open — условие о прошлом. I would have walked — действие, которое тогда могло произойти.","question":"Choose the correct third conditional.","explanation":"If the bridge had been open, I would have walked across it. Had been задаёт нереальное условие в прошлом, would have walked — его результат."},"n13":{"speaker":"Narrator","text":"You tell another visitor why you changed your route, and she understands immediately. She is heading to the afternoon session. There is no extra fee to switch, provided you show the original ticket. The ferry is boarding now; the covered market is a short walk from this bank.","choices":[{"id":"a","text":"Decide what matters most today.","next":"n15"}],"vocabulary":[{"word":"provided","translation":"при условии что"}]},"n14":{"speaker":"Narrator","text":"You revise your sentence: \"If the bridge had been open, I would have walked across it.\" While you practise, a ferry volunteer checks your ticket. The morning boat is almost full. You can join the afternoon workshop or make a new plan on this side of the river.","choices":[{"id":"a","text":"Choose a realistic alternative.","next":"n16"}],"vocabulary":[{"word":"revise","translation":"исправлять; пересматривать"}]},"n15":{"speaker":"Ferry volunteer","text":"There is one place left. If you board now, you should reach the morning workshop on time. Alternatively, the afternoon session will give you more room to explore the market and understand the city’s changing signs. Neither choice changes the validity of your ticket.","choices":[{"id":"a","text":"Take the ferry to the morning workshop.","next":"n17"},{"id":"b","text":"Switch to the sheltered afternoon session.","next":"n18"}],"vocabulary":[{"word":"validity","translation":"действительность; срок действия"}]},"n16":{"speaker":"Narrator","text":"The next ferry will arrive after the morning session begins. The organiser confirms your afternoon place by checking the printed ticket. You can accept it, or skip the workshop and follow the free self-guided walk printed on the back of your festival map.","choices":[{"id":"a","text":"Accept the afternoon workshop place.","next":"n18"},{"id":"b","text":"Choose the self-guided city walk.","next":"n19"}],"vocabulary":[{"word":"self-guided","translation":"самостоятельный, без экскурсовода"}]},"n17":{"speaker":"Narrator","text":"You reach North Quay as the instructor sets out sketchbooks. When the rain begins, the group draws the shifting reflections beneath a canopy. Your sketch includes both names for the quay. You have kept your original appointment, and the journey has given you a subject you could not have planned.","choices":[],"vocabulary":[{"word":"canopy","translation":"навес"}],"ending":{"title":"Рисунок у северного причала","reward":"Значок «Маршрут найден»"}},"n18":{"speaker":"Narrator","text":"At the covered market, you learn why residents still use the old street names. Your afternoon sketch layers the foundry’s outline over the modern quay. The workshop begins with your question about changing signs. By adjusting your timetable, you have turned a confusing arrival into the theme of your visit.","choices":[],"vocabulary":[{"word":"layers","translation":"накладывает слоями"}],"ending":{"title":"Город с двумя именами","reward":"Значок «Гибкий путешественник»"}},"n19":{"speaker":"Narrator","text":"You follow the map’s free walk past the mill, the market and a wall of historic street signs. You miss the workshop, but write a short travel note explaining each detour. At the station, you help another visitor match North Quay to Foundry Steps. The unfamiliar city is already easier to describe.","choices":[],"vocabulary":[{"word":"detour","translation":"обходной путь"}],"ending":{"title":"Собственная карта города","reward":"Значок «Исследователь переулков»"}}}}'::jsonb) ON CONFLICT(slug,revision) DO NOTHING;
INSERT INTO public.interactive_stories(slug,revision,title,subtitle,description,level,minutes,free_preview,published,document) VALUES('secret-message',1,'Секретное сообщение','The Margin Between the Lines','В библиотечном буклете найдено сообщение без подписи. Проверь контекст, восстанови последовательность подсказок и реши, стоит ли делать находку публичной.','B2',18,false,true,'{"start":"n1","nodes":{"n1":{"speaker":"Narrator","text":"While volunteering at a community library, you find a pencilled note inside an old exhibition booklet: \"The answer is not in the headline. Read what we nearly left out.\" Tomorrow the library will display the booklet online. The note might be a puzzle, an editing instruction or a private message.","choices":[{"id":"a","text":"Examine the booklet’s margins.","next":"n2"},{"id":"b","text":"Ask the librarian about the exhibition.","next":"n3"}],"vocabulary":[{"word":"margin","translation":"поле страницы"}]},"n2":{"speaker":"Narrator","text":"Several captions have tiny numbers in their margins. The numbers are printed, whereas the note is in pencil. One caption has been crossed out on a loose proof sheet. Its subject is a volunteer-built reading room that never appeared in the final exhibition title.","choices":[{"id":"a","text":"Compare the proof with the published booklet.","next":"n4"}],"vocabulary":[{"word":"proof sheet","translation":"корректурный лист"}]},"n3":{"speaker":"Librarian","text":"The exhibition celebrated a famous architect, but volunteers built the reading room before he redesigned it. Some captions were shortened to fit the pages. The librarian remembers an editor who disliked the omissions. She gives you a public catalogue record, not the editor’s private contact details.","choices":[{"id":"a","text":"Check the catalogue against the booklet.","next":"n4"}],"vocabulary":[{"word":"omission","translation":"пропуск; упущение"}]},"n4":{"speaker":"Narrator","text":"The public record credits the volunteers, while the final booklet mentions only the architect. The note could be a reminder to restore that credit. You should distinguish a plausible explanation from an established fact before presenting the discovery to tomorrow’s visitors.","choices":[{"id":"a","text":"Summarise what the note might mean.","next":"n5"}],"vocabulary":[{"word":"plausible","translation":"правдоподобный"}],"grammar":"Модальные глаголы о прошлом: might have been — возможно, было; must have been — уверенный вывод по веским основаниям."},"n5":{"speaker":"Librarian","text":"Do we know who wrote the pencilled note? You have no handwriting sample and no signed record. Which statement reflects the uncertainty rather than inventing certainty?","choices":[{"id":"a","text":"It might have been written by an editor.","next":"n6","correct":true},{"id":"b","text":"It must have been written by the architect himself.","next":"n7","correct":false}],"vocabulary":[{"word":"uncertainty","translation":"неопределённость"}],"grammar":"Might + have + been + V3: предположение о том, кем действие было совершено в прошлом.","question":"Choose a cautious conclusion.","explanation":"It might have been written by an editor. Might have been передаёт возможное объяснение. Must have been by the architect утверждает уверенность, для которой нет оснований."},"n6":{"speaker":"Librarian","text":"Exactly. We can investigate the message without claiming to know its author. She suggests treating the numbered captions as a possible reading order. You copy the public text, keeping the pencilled original in its protective sleeve so it will not be damaged.","choices":[{"id":"a","text":"Choose how to test the reading order.","next":"n8"}],"vocabulary":[{"word":"sleeve","translation":"защитный конверт; чехол"}]},"n7":{"speaker":"Narrator","text":"The librarian asks what evidence connects the architect to the handwriting. You have none. You replace \"must\" with \"might\" in your draft. The correction matters: a confident guess could become a false attribution once the booklet is published online.","choices":[{"id":"a","text":"Continue with the numbered captions.","next":"n8"}],"vocabulary":[{"word":"attribution","translation":"указание авторства"}]},"n8":{"speaker":"Narrator","text":"The numbers could indicate page order or caption order. You can sort the first words of the captions by their small printed numbers, or compare those numbers with the original layout plan. Both methods use public documents already approved for the exhibition.","choices":[{"id":"a","text":"Read the first words in number order.","next":"n9"},{"id":"b","text":"Compare the original layout plan.","next":"n10"}],"vocabulary":[{"word":"layout","translation":"макет; расположение элементов"}]},"n9":{"speaker":"Narrator","text":"The first words form a phrase: \"Remember those who made room.\" It is meaningful, but not proof of a deliberate code. The omitted caption begins with \"Together\". You mark the phrase as a possible pattern and look for a document that explains the numbers.","choices":[{"id":"a","text":"Search the public editing notes.","next":"n11"}],"vocabulary":[{"word":"deliberate","translation":"намеренный"}]},"n10":{"speaker":"Narrator","text":"The layout plan numbers captions to guide the printer. However, an attached public editing note asks that their opening words remain unchanged. That unusual request makes the first words worth reading in order. The omitted caption begins with \"Together\" and completes the phrase.","choices":[{"id":"a","text":"Find the full editing note.","next":"n11"}],"vocabulary":[{"word":"attached","translation":"приложенный"}]},"n11":{"speaker":"Narrator","text":"The editing note says: \"Please retain the opening words; together they acknowledge the reading-room volunteers.\" It establishes the editor’s intention for the printed pattern, though not the identity of the pencilled-note writer. You need to report the instruction accurately without changing its meaning.","choices":[{"id":"a","text":"Turn the instruction into reported speech.","next":"n12"}],"vocabulary":[{"word":"retain","translation":"сохранять"}],"grammar":"Reported instructions: asked + дополнение + to + глагол. Например: The editor asked us to retain the opening words."},"n12":{"speaker":"Librarian","text":"What did the editor ask the printer to do? The written instruction was \"Please retain the opening words.\" Choose an accurate report of that request.","choices":[{"id":"a","text":"The editor asked the printer to retain the opening words.","next":"n13","correct":true},{"id":"b","text":"The editor asked the printer retaining the opening words.","next":"n14","correct":false}],"vocabulary":[{"word":"opening words","translation":"первые слова"}],"grammar":"Ask someone to do something — попросить кого-либо сделать что-либо.","question":"Choose the correct reported instruction.","explanation":"The editor asked the printer to retain the opening words. Asked + someone + to do передаёт просьбу. Вариант asked… retaining здесь неверен."},"n13":{"speaker":"Librarian","text":"That is precise. The message acknowledges the volunteers, and the catalogue supports restoring their credit. We can update the public display with a verified explanation, or host a small discussion about whose work disappears when an exhibition is shortened. The unknown handwriting can remain unknown.","choices":[{"id":"a","text":"Choose how to present the discovery.","next":"n15"}],"vocabulary":[{"word":"acknowledge","translation":"признавать вклад"}]},"n14":{"speaker":"Narrator","text":"You rewrite the sentence using \"asked the printer to retain\". The librarian accepts the corrected translation of the request, but the display team has already started uploading the booklet. You can request a reviewed addendum or leave your research in the library’s discovery file for later work.","choices":[{"id":"a","text":"Choose a responsible next step.","next":"n16"}],"vocabulary":[{"word":"addendum","translation":"дополнение к документу"}]},"n15":{"speaker":"Narrator","text":"You have enough evidence to explain the caption pattern and credit the volunteers. You do not have enough to name the pencilled-note writer. Visitors will see whichever presentation you choose, so its limits should be as visible as its conclusion.","choices":[{"id":"a","text":"Publish an explanation with sources and limits.","next":"n17"},{"id":"b","text":"Arrange a discussion beside the original booklet.","next":"n18"}],"vocabulary":[{"word":"limits","translation":"границы; ограничения"}]},"n16":{"speaker":"Librarian","text":"The original booklet will stay online unchanged as a historical document. A separate note can explain the missing credit without silently rewriting the source. If there is no time to review it today, your evidence can remain in the discovery file until another volunteer continues the work.","choices":[{"id":"a","text":"Request a separately reviewed addendum.","next":"n18"},{"id":"b","text":"Archive the evidence for a future researcher.","next":"n19"}],"vocabulary":[{"word":"silently","translation":"незаметно; без пояснений"}]},"n17":{"speaker":"Narrator","text":"The online display includes a sourced explanation of the first-word pattern and names the volunteer group from the public catalogue. A final line states that the pencilled note’s author is unknown. The secret is smaller than a sensational headline, but the restored credit makes the history more complete.","choices":[],"vocabulary":[{"word":"sourced","translation":"подтверждённый источниками"}],"ending":{"title":"Имена возвращены","reward":"Значок «Внимательный исследователь»"}},"n18":{"speaker":"Narrator","text":"The library presents the booklet with a reviewed companion note and invites visitors to discuss the missing credit. A former reading-room volunteer brings a public photograph for a future display. Nobody claims it identifies the handwriting. Your careful language has opened a conversation rather than closed an uncertain case.","choices":[],"vocabulary":[{"word":"companion note","translation":"сопроводительное примечание"}],"ending":{"title":"Разговор на полях","reward":"Значок «Хранитель контекста»"}},"n19":{"speaker":"Narrator","text":"You file the captions, the catalogue reference and the editing instruction together, separating facts from unanswered questions. Tomorrow’s display proceeds without your theory. Weeks later, another volunteer can follow your reasoning without starting again. A message need not be completely solved to be responsibly preserved.","choices":[],"vocabulary":[{"word":"preserved","translation":"сохранённый"}],"ending":{"title":"След для следующего читателя","reward":"Значок «Честная неопределённость»"}}}}'::jsonb) ON CONFLICT(slug,revision) DO NOTHING;
